package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.profile.dto.*; import com.scriptles.cabinet.profile.entity.CatalogOrganization; import com.scriptles.cabinet.profile.enums.OrganizationType; import com.scriptles.cabinet.profile.repository.CatalogOrganizationRepository; import com.scriptles.cabinet.profile.service.ProfileService; import com.scriptles.cabinet.security.AuthenticatedUser; import com.scriptles.cabinet.user.repository.UserRepository; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/moderation/hq") @RequiredArgsConstructor public class HQBootstrapController { private final CatalogOrganizationRepository organizations; private final ProfileService profiles; private final UserRepository users;
 @PostMapping public ProfileResponse create(@AuthenticationPrincipal AuthenticatedUser actor,@Valid @RequestBody CreateHQRequest request){if(!actor.admin()) throw new com.scriptles.cabinet.common.api.ApiException(HttpStatus.FORBIDDEN,"HQ_FORBIDDEN","Apenas administradores podem criar HQs"); CatalogOrganization o=organizations.findByPrimarySourceAndPrimaryExternalId(request.source(),request.externalId()).orElseGet(CatalogOrganization::new);o.setType(type(request.type()));o.setCanonicalName(request.name());o.setPrimarySource(request.source());o.setPrimaryExternalId(request.externalId());o.setWebsiteUrl(request.websiteUrl());o.setCountryCode(request.countryCode());o.setLogoUrl(request.logoUrl());o.setDescription(request.description());o=organizations.save(o);var existing=profiles.existingHQ(o.getPrimarySource(),o.getPrimaryExternalId());if(existing.isPresent()) return profiles.find(existing.get().getHandle(),actor.id());var owner=users.findById(request.ownerAccountId()==null?actor.id():request.ownerAccountId()).orElseThrow(()->new com.scriptles.cabinet.common.api.ApiException(HttpStatus.NOT_FOUND,"ACCOUNT_NOT_FOUND","Conta não encontrada"));var p=profiles.createOfficialHQ(o,request.type(),request.handle(),owner);return profiles.find(p.getHandle(),actor.id());}
 private OrganizationType type(com.scriptles.cabinet.profile.enums.HQType type){return switch(type){case FILM_STUDIO->OrganizationType.FILM_STUDIO;case PRODUCTION_COMPANY->OrganizationType.PRODUCTION_COMPANY;case TV_NETWORK->OrganizationType.NETWORK;case DISTRIBUTOR->OrganizationType.DISTRIBUTOR;case RECORD_LABEL->OrganizationType.RECORD_LABEL;case MUSIC_DISTRIBUTOR->OrganizationType.MUSIC_DISTRIBUTOR;default->OrganizationType.OTHER;};}}
